import {jest} from '@jest/globals';

import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  afterEach(() => setLogger(undefined));

  // specs/hal-engine-tool-input-validation/spec.md#1
  it('returns a ToolResponse naming the missing required field and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    expect({result: response.result, executorCalls: executor.mock.calls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: [],
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names an enum constraint without exposing the rejected value', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'unreachable');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['metric', 'imperial']}},
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {units: 'private-units'});

    expect({
      mentionsConstraint: /units.*enum|enum.*units/i.test(response.result),
      leaksValue: response.result.includes('private-units'),
      executorCalls: executor.mock.calls,
    }).toEqual({mentionsConstraint: true, leaksValue: false, executorCalls: []});
  });

  // specs/hal-engine-tool-input-validation/spec.md#2
  it('logs the rejected field and expected type without logging its value', async () => {
    const logInfo = jest.fn();
    setLogger({debug: jest.fn(), info: logInfo, warn: jest.fn(), error: jest.fn()});
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'unreachable');
    registry.register(
      {
        name: 'lookup',
        description: 'Look up an identifier',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}},
      },
      executor
    );

    const response = await registry.execute('lookup', {identifier: 8675309});

    const logOutput = JSON.stringify(logInfo.mock.calls);
    expect({
      resultMentionsField: response.result.includes('identifier'),
      resultMentionsExpectedType: response.result.includes('string'),
      resultLeaksValue: response.result.includes('8675309'),
      logsMentionField: logOutput.includes('identifier'),
      logsMentionExpectedType: logOutput.includes('string'),
      logsLeakValue: logOutput.includes('8675309'),
      executorCalls: executor.mock.calls,
    }).toEqual({
      resultMentionsField: true,
      resultMentionsExpectedType: true,
      resultLeaksValue: false,
      logsMentionField: true,
      logsMentionExpectedType: true,
      logsLeakValue: false,
      executorCalls: [],
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#4
  it('passes valid input with an unknown property to the executor unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    const input = {location: 'Berlin', requestId: 'weather-123'};
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    await registry.execute('get_weather', input);

    expect(executor.mock.calls).toEqual([[input, undefined]]);
  });

  // specs/hal-engine-tool-input-validation/spec.md#5
  it('compiles a static schema at registration and names the tool when the schema is invalid', () => {
    const registry = new ToolRegistry();
    const invalidDefinition = {
      name: 'broken_weather',
      description: 'Has an invalid JSON Schema type',
      inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
    };

    expect(() => registry.register(invalidDefinition, async () => 'unreachable')).toThrow(/broken_weather/);
  });

  // specs/hal-engine-tool-input-validation/spec.md#7
  it('validates each call against the schema returned for that call', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'matched');
    let requiresPostalCode = false;
    registry.register(
      () => ({
        name: 'lookup',
        description: 'Look up a place',
        inputSchema: {
          type: 'object',
          properties: requiresPostalCode ? {postalCode: {type: 'number'}} : {location: {type: 'string'}},
          required: [requiresPostalCode ? 'postalCode' : 'location'],
        },
      }),
      executor
    );

    await registry.execute('lookup', {location: 'Berlin'});
    requiresPostalCode = true;
    const rejected = await registry.execute('lookup', {location: 'Berlin'});

    expect({executorCalls: executor.mock.calls, rejected: rejected.result}).toEqual({
      executorCalls: [[{location: 'Berlin'}, undefined]],
      rejected: expect.stringMatching(/postalCode.*required|required.*postalCode/i),
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#5
  it('throws the unchanged unknown-tool error for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

function formatValidationError(error: ErrorObject): string {
  if (error.keyword === 'required' && 'missingProperty' in error.params) {
    return `Tool input property ${String(error.params['missingProperty'])} is required`;
  }
  if (error.keyword === 'type' && 'type' in error.params) {
    return `Tool input ${errorPath(error)} must be ${String(error.params['type'])}`;
  }
  if (error.keyword === 'enum') {
    return `Tool input ${errorPath(error)} failed its enum constraint`;
  }
  return `Tool input ${errorPath(error)} ${error.message ?? 'is invalid'}`;
}

function errorPath(error: ErrorObject): string {
  const paths = error as unknown as {instancePath?: unknown; dataPath?: unknown};
  if (typeof paths.instancePath === 'string' && paths.instancePath) return paths.instancePath;
  if (typeof paths.dataPath === 'string' && paths.dataPath) return paths.dataPath;
  return '/';
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validate) return tool.validate;
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) return cached;
    const validate = ajv.compile(definition.inputSchema);
    this.dynamicValidators.set(definition.inputSchema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a tool under the contract in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (!validate(input)) {
      const error = validate.errors?.[0];
      const result = error ? formatValidationError(error) : 'Tool input is invalid';
      log.info('tool', 'input rejected', {name, reason: result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a ToolResponse naming the missing required field and does not invoke the executor](../../src/orchestration/tools/registry.test.ts#L10); [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` and emits a rejection log naming the failing field path and expected type without invoking the executor, and neither output contains the offending property value ([validated by: logs the rejected field and expected type without logging its value](../../src/orchestration/tools/registry.test.ts#L60); [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When an `enum` constraint rejects a property, the rejection names the property path and the `enum` constraint without exposing the rejected value ([validated by: names an enum constraint without exposing the rejected value](../../src/orchestration/tools/registry.test.ts#L35)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an unknown property to the executor unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L97)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws the unchanged unknown-tool error for an unregistered name](../../src/orchestration/tools/registry.test.ts#L159)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: compiles a static schema at registration and names the tool when the schema is invalid](../../src/orchestration/tools/registry.test.ts#L120); [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each call against the schema returned for that call](../../src/orchestration/tools/registry.test.ts#L132)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: lets the model correct a schema-rejected tool call on the next round](../../src/orchestration/chatOrchestrator.test.ts#L524); [validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
